import argparse
import csv
import json
import os
import random
from collections import defaultdict

def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument('--input_path', required=True)
    parser.add_argument('--output_dir', required=True)
    parser.add_argument('--seed', type=int, default=42)
    return parser.parse_args()

def parse_csv(filepath):
    rows = []
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            parts = line.split(',', 1)
            if len(parts) == 1:
                identifier, tags = parts[0], ''
            else:
                identifier, tags = parts[0], parts[1]
            tags = tags.strip()
            tags_list = [t.strip() for t in tags.split(',') if t.strip() or t.strip() == '']
            rows.append({
                'identifier': identifier,
                'tags': tags_list,
                'raw_tags': tags
            })
    return rows

def normalize_tags(tags_list):
    """Normalize tags: sort alphabetically, remove extra spaces."""
    tags = [t.strip() for t in tags_list]
    tags.sort()
    return ','.join(tags)

def get_label_distribution(rows, group_name):
    """Get label distribution for a group."""
    dist = defaultdict(int)
    for row in rows:
        for tag in row['tags']:
            dist[tag] += 1
    return dict(sorted(dist.items()))

def get_label_combinations(rows, group_name):
    """Get label combination distribution for a group."""
    combos = defaultdict(int)
    for row in rows:
        combo = normalize_tags(row['tags'])
        combos[combo] += 1
    return dict(sorted(combos.items()))

def iterative_stratification(rows, targets=(0.7, 0.15, 0.15), seed=42):
    random.seed(seed)

    all_tag_counts = defaultdict(int)
    all_combo_counts = defaultdict(int)

    for row in rows:
        for tag in row['tags']:
            all_tag_counts[tag] += 1
        combo = normalize_tags(row['tags'])
        all_combo_counts[combo] += 1

    sorted_tags = sorted(all_tag_counts.keys(), key=lambda t: -all_tag_counts[t])
    sorted_combos = sorted(all_combo_counts.keys(), key=lambda c: -all_combo_counts[c])

    samples = list(rows)
    random.shuffle(samples)

    n = len(samples)
    target_n = [int(n * t) for t in targets]
    remainder = n - sum(target_n)
    for i in range(remainder):
        target_n[i] += 1

    train = []
    val = []
    test = []

    def get_rarity(sample):
        tags = sample['tags']
        tag_rarity = 0
        for tag in tags:
            tag_rarity += 1.0 / max(1, all_tag_counts.get(tag, 0))
        combo = normalize_tags(tags)
        combo_rarity = 1.0 / max(1, all_combo_counts.get(combo, 0))
        return tag_rarity + combo_rarity

    samples_with_rarity = [(get_rarity(row), row) for row in samples]
    samples_with_rarity.sort(key=lambda x: x[0])

    for rarity, sample in samples_with_rarity:
        current_train = len(train)
        current_val = len(val)
        current_test = len(test)

        diff_train = abs(current_train / n - target_n[0] / n)
        diff_val = abs(current_val / n - target_n[1] / n)
        diff_test = abs(current_test / n - target_n[2] / n)

        max_diff = max(diff_train, diff_val, diff_test)
        if diff_train == max_diff:
            if diff_val == max_diff:
                if diff_test == max_diff:
                    if len(train) <= len(val) and len(train) <= len(test):
                        group = 'train'
                    elif len(val) <= len(test):
                        group = 'val'
                    else:
                        group = 'test'
                else:
                    group = 'train'
            else:
                group = 'train'
