                    group = 'val'
                else:
                    group = 'test'
            else:
                group = 'val'
        else:
            group = 'test'

        if group == 'train':
            train.append(sample)
        elif group == 'val':
            val.append(sample)
        else:
            test.append(sample)

    return train, val, test

