    os.makedirs(args.output_dir, exist_ok=True)

    rows = parse_csv(args.input_path)

    train, val, test = iterative_stratification(rows, targets=(0.7, 0.15, 0.15), seed=args.seed)

    def write_output(group_name, group, filepath):
        with open(filepath, 'w') as f:
            for row in group:
                tags = normalize_tags(row['tags'])
                f.write(f"{row['identifier']},{tags}\n")

    write_output('train', train, os.path.join(args.output_dir, 'train.csv'))
    write_output('val', val, os.path.join(args.output_dir, 'val.csv'))
